sysauto_script.script:
(function executeRule() {

    // Find records where expiry is exactly 10 days from today
    var gr = new GlideRecord("x_vuram_financia_0_fcc_kyc_individual_details"); // table name
    var targetDate = new GlideDateTime();
    targetDate.addDaysLocalTime(10); // add 10 days

    gr.addQuery("kyc_expiry", targetDate.getDate()); // expiry date = today + 10
    gr.query();

    while (gr.next()) {
        // Fire the event for 10 days prior notification
        gs.eventQueue("x_vuram_financia_0.kyc.review.individual", gr, "", "");

        gs.info("10 days prior KYC expiry notification fired for record: " + gr.sys_id);
    }

})();


